import{_ as o,o as c,c as d,a2 as E}from"./chunks/framework.Bg-Zxr5O.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/MRSETS.md","filePath":"manual-zh/MRSETS.md","lastUpdated":1785684581000}'),A={name:"manual-zh/MRSETS.md"};function L(l,e,a,t,S,i){return c(),d("div",null,[...e[0]||(e[0]=[E(`<h3 id="_11-20-mrsets" tabindex="-1">11.20 MRSETS <a class="header-anchor" href="#_11-20-mrsets" aria-label="Permalink to &quot;11.20 MRSETS&quot;">​</a></h3><p><code>MRSETS</code> 创建、修改、删除并显示多重响应集（multiple response sets）。多重响应集是一组代表对调查问题多重响应的变量。</p><p>多重响应以下列两种方式之一表示：</p><ul><li><p><em>多重二分集</em>（multiple dichotomy set）类似于一组复选框的调查问题。集合中的每个变量以布尔方式处理：一个值（“计数值”，counted value）表示复选框被选中，任何其他值表示未被选中。</p></li><li><p><em>多重类别集</em>（multiple category set）表示受访者被要求列出最多 n 个选择的调查问题。每个变量代表其中一个响应。</p><p>MRSETS /MDGROUP NAME=name VARIABLES=var_list VALUE=value [CATEGORYLABELS={VARLABELS,COUNTEDVALUES}] [{LABEL=’label’,LABELSOURCE=VARLABEL}]</p><pre><code>/MCGROUP NAME=name VARIABLES=var_list [LABEL=’label’]

/DELETE NAME={[names],ALL}

/DISPLAY NAME={[names],ALL}
</code></pre></li></ul><p>可以按任意顺序指定任意数量的子命令。</p><p><code>MDGROUP</code> 子命令创建一个新的多重二分集或替换现有的多重响应集。<code>NAME</code>、<code>VARIABLES</code> 和 <code>VALUE</code> 说明是必需的。其他都是可选的：</p><ul><li>NAME 指定在语法中用于新多重二分集的名称。名称必须以‘$’开头；除此之外必须遵循标识符的规则（参见 <a href="./Tokens">Tokens</a>）。</li><li><code>VARIABLES</code> 指定属于该集合的变量。必须至少指定两个变量。这些变量必须全为字符串或全为数值。</li><li><code>VALUE</code> 指定计数值。如果变量是数值型，则该值必须为整数。如果变量是字符串型，则该值必须是长度不超过集合中变量最短长度（忽略尾随空格）的字符串。</li><li><code>CATEGORYLABELS</code> 可选地指定集合中每个类别标签的来源： <ul><li>- <code>VARLABELS</code>，默认值，使用变量标签，或者对于没有变量标签的变量，使用变量名。如果两个变量具有相同的变量标签，PSPP 会发出警告，因为这些类别在输出中无法区分。</li><li>- <code>COUNTEDVALUES</code> 则使用每个变量计数值的值标签。如果两个变量对计数值具有相同的值标签，或者其中一个变量缺少值标签，PSPP 会发出警告，因为这些类别在输出中无法区分。</li></ul></li><li><code>LABEL</code> 可选地指定多重响应集的标签。如果既未指定 <code>LABEL</code> 也未指定 <code>LABELSOURCE=VARLABEL</code>，则该集无标签。</li><li><code>LABELSOURCE=VARLABEL</code> 从集合中变量的第一个变量标签获取多重响应集的标签；如果没有变量具有标签，则使用第一个变量的名称。<code>LABELSOURCE=VARLABEL</code> 必须与 <code>CATEGORYLABELS=COUNTEDVALUES</code> 一起使用。它与 <code>LABEL</code> 互斥。</li></ul><p><code>MCGROUP</code> 子命令创建一个新的多重类别集或替换现有的多重响应集。<code>NAME</code> 和 <code>VARIABLES</code> 说明是必需的，<code>LABEL</code> 是可选的。它们的含义如上面 <code>MDGROUP</code> 中所述。如果集合中的两个变量对单个值具有不同的值标签，PSPP 会发出警告，因为集合中的每个变量应该具有相同的可能类别。</p><p><code>DELETE</code> 子命令删除多重响应组。可以在一组必需的方括号内命名一组组，或者使用 ALL 删除所有组。</p><p><code>DISPLAY</code> 子命令显示关于已定义多重响应集的信息。其语法与 <code>DELETE</code> 子命令相同。</p><p>多重响应集由例如 <code>SAVE</code> 和 <code>GET</code> 命令保存至系统文件并从中读取。除此之外，多重响应集目前仅被第三方软件使用。</p>`,11)])])}const s=o(A,[["render",L]]);export{n as __pageData,s as default};
